import React from "react";

// 记录已收藏的网页
var favourite_websites_received = [];

class DisplayFavourite extends React.Component {
  render() {
    return (
      <div>
        {favourite_websites_received[0] !== undefined && (
          <React.Fragment>
            {favourite_websites_received.map((favourite_individual) => (
              <div key={favourite_individual.position}>
                <h6 className="card-body">
                  <Link
                    target="_blank"
                    to={
                      "//" +
                      (result_individual.link[4] === "s"
                        ? // https
                          result_individual.link.slice(
                            8,
                            result_individual.link.length
                          )
                        : // http
                          result_individual.link.slice(
                            7,
                            result_individual.link.length
                          ))
                    }
                  >
                    {result_individual.title}
                  </Link>
                  <div
                    id="search-result-display-link"
                    className="card-subtitle mb-2 text-muted"
                  >
                    {result_individual.displayed_link}
                  </div>
                  <div>{result_individual.snippet}</div>
                </h6>
                <button
                  className="add-favourite-webpages"
                  onClick={() =>
                    this.changeFavouriteWebpagesButtonStatus(result_individual)
                  }
                ></button>
              </div>
            ))}
          </React.Fragment>
        )}
      </div>
    );
  }
}

class Favourite extends React.Component {
  render() {
    let { favourite_websites } = this.props;
    if (favourite_websites) {
      favourite_websites_received = favourite_websites;
    }
    return (
      <React.Fragment>
        {this.props.match !== undefined &&
          this.props.match.url === "/favourite" && (
            <DisplayFavourite {...this.props} />
          )}
      </React.Fragment>
    );
  }
}

export default Favourite;
